import React, { useState } from "react";
import {
  Gift,
  Heart,
  ShoppingBag,
  Sparkles,
  Menu,
  X,
  Star,
  Truck,
  PackageCheck,
  Leaf,
  ChevronRight,
  Plus,
  Minus,
  Flame,
  BookOpen,
  Coffee,
  Gem,
  Cookie,
} from "lucide-react";

const COLORS = {
  plum: "#2D1B4E",
  violet: "#6B3FA0",
  orchid: "#B565D8",
  gold: "#E8B84B",
  cream: "#FBF7FF",
  ink: "#1A1425",
};

const OCCASIONS = ["Birthdays", "Anniversaries", "Just Because", "Housewarming", "Thank You", "New Baby"];

const PRODUCTS = [
  { id: 1, name: "Ember & Oak Candle", tag: "Candles", price: 28, icon: Flame, from: COLORS.violet, to: COLORS.orchid },
  { id: 2, name: "Quiet Hours Journal", tag: "Stationery", price: 22, icon: BookOpen, from: COLORS.gold, to: COLORS.violet },
  { id: 3, name: "Morning Ritual Mug", tag: "Home", price: 18, icon: Coffee, from: COLORS.orchid, to: COLORS.plum },
  { id: 4, name: "Little Fern Planter", tag: "Green", price: 24, icon: Leaf, from: COLORS.violet, to: COLORS.gold },
  { id: 5, name: "Keepsake Trinket Box", tag: "Jewelry", price: 34, icon: Gem, from: COLORS.plum, to: COLORS.orchid },
  { id: 6, name: "Sweet Nothings Box", tag: "Treats", price: 20, icon: Cookie, from: COLORS.gold, to: COLORS.orchid },
];

function ProductCard({ product, onAdd }) {
  const Icon = product.icon;
  return (
    <div className="flex flex-col rounded-2xl overflow-hidden border" style={{ borderColor: "#EADFF7" }}>
      <div
        className="h-40 flex items-center justify-center"
        style={{ background: `linear-gradient(135deg, ${product.from}, ${product.to})` }}
      >
        <Icon color="#fff" size={40} strokeWidth={1.5} />
      </div>
      <div className="p-4 flex flex-col gap-1" style={{ backgroundColor: COLORS.cream }}>
        <span className="text-xs uppercase tracking-wide" style={{ color: COLORS.violet }}>
          {product.tag}
        </span>
        <h3 className="text-base font-medium" style={{ color: COLORS.ink, fontFamily: "'Fraunces', serif" }}>
          {product.name}
        </h3>
        <div className="flex items-center justify-between mt-2">
          <span className="text-lg font-semibold" style={{ color: COLORS.ink }}>
            ${product.price}
          </span>
          <button
            onClick={() => onAdd(product)}
            className="text-sm px-3 py-1.5 rounded-full flex items-center gap-1 transition-transform hover:scale-105"
            style={{ backgroundColor: COLORS.violet, color: "#fff" }}
          >
            <Plus size={14} /> Add
          </button>
        </div>
      </div>
    </div>
  );
}

export default function App() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [cartOpen, setCartOpen] = useState(false);
  const [cart, setCart] = useState([]);

  const addToCart = (product) => {
    setCart((prev) => {
      const existing = prev.find((i) => i.id === product.id);
      if (existing) {
        return prev.map((i) => (i.id === product.id ? { ...i, qty: i.qty + 1 } : i));
      }
      return [...prev, { ...product, qty: 1 }];
    });
    setCartOpen(true);
  };

  const changeQty = (id, delta) => {
    setCart((prev) =>
      prev
        .map((i) => (i.id === id ? { ...i, qty: i.qty + delta } : i))
        .filter((i) => i.qty > 0)
    );
  };

  const cartCount = cart.reduce((sum, i) => sum + i.qty, 0);
  const cartTotal = cart.reduce((sum, i) => sum + i.qty * i.price, 0);

  return (
    <div style={{ backgroundColor: COLORS.cream, fontFamily: "'Poppins', sans-serif", color: COLORS.ink }} className="min-h-screen w-full relative">
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600&family=Poppins:wght@300;400;500;600&display=swap');
        @keyframes floatSlow { 0%,100% { transform: translateY(0px); } 50% { transform: translateY(-10px); } }
        @keyframes sparklePop { 0% { opacity: 0; transform: scale(0.6); } 60% { opacity: 1; } 100% { opacity: 0; transform: scale(1.1) translateY(-6px); } }
        .giftbox-lid { transition: transform 0.5s ease, box-shadow 0.5s ease; transform-origin: 20% 100%; }
        .giftbox-group:hover .giftbox-lid { transform: rotate(-22deg) translate(-6px,-10px); }
        .giftbox-group:hover .sparkle-1 { animation: sparklePop 1.1s ease forwards; }
        .giftbox-group:hover .sparkle-2 { animation: sparklePop 1.1s ease 0.15s forwards; }
        .giftbox-group:hover .sparkle-3 { animation: sparklePop 1.1s ease 0.3s forwards; }
      `}</style>

      {/* Navbar */}
      <header className="sticky top-0 z-30" style={{ backgroundColor: "rgba(251,247,255,0.9)", backdropFilter: "blur(6px)", borderBottom: "1px solid #EADFF7" }}>
        <div className="max-w-6xl mx-auto px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Gift size={22} color={COLORS.violet} />
            <span className="text-lg" style={{ fontFamily: "'Fraunces', serif", fontWeight: 600, color: COLORS.plum }}>
              The Purple Gifts
            </span>
          </div>
          <nav className="hidden md:flex items-center gap-8 text-sm">
            {["Shop", "Occasions", "Journal", "About"].map((item) => (
              <a key={item} href="#" className="hover:opacity-70" style={{ color: COLORS.ink }}>
                {item}
              </a>
            ))}
          </nav>
          <div className="flex items-center gap-4">
            <Heart size={20} className="hidden sm:block cursor-pointer" color={COLORS.plum} />
            <button onClick={() => setCartOpen(true)} className="relative">
              <ShoppingBag size={20} color={COLORS.plum} />
              {cartCount > 0 && (
                <span
                  className="absolute -top-2 -right-2 text-xs w-4 h-4 rounded-full flex items-center justify-center"
                  style={{ backgroundColor: COLORS.gold, color: COLORS.ink }}
                >
                  {cartCount}
                </span>
              )}
            </button>
            <button className="md:hidden" onClick={() => setMenuOpen(!menuOpen)}>
              {menuOpen ? <X size={22} /> : <Menu size={22} />}
            </button>
          </div>
        </div>
        {menuOpen && (
          <div className="md:hidden px-6 pb-4 flex flex-col gap-3 text-sm">
            {["Shop", "Occasions", "Journal", "About"].map((item) => (
              <a key={item} href="#">{item}</a>
            ))}
          </div>
        )}
      </header>

      {/* Hero */}
      <section className="max-w-6xl mx-auto px-6 py-16 md:py-24 flex flex-col md:flex-row items-center gap-12">
        <div className="flex-1">
          <span className="inline-flex items-center gap-2 text-xs uppercase tracking-widest px-3 py-1 rounded-full" style={{ backgroundColor: "#EADFF7", color: COLORS.violet }}>
            <Sparkles size={12} /> Small-batch gifting
          </span>
          <h1 className="mt-5 text-4xl md:text-5xl leading-tight" style={{ fontFamily: "'Fraunces', serif", fontWeight: 500, color: COLORS.plum }}>
            Wrapped in wonder,
            <br /> chosen with care.
          </h1>
          <p className="mt-4 text-base md:text-lg max-w-md" style={{ color: "#5B4A73" }}>
            Every piece in our shop is picked for the moment right before someone opens it — that small breath of surprise.
          </p>
          <div className="mt-8 flex items-center gap-4">
            <a href="#shop" className="px-6 py-3 rounded-full text-sm font-medium" style={{ backgroundColor: COLORS.violet, color: "#fff" }}>
              Explore gifts
            </a>
            <a href="#occasions" className="flex items-center gap-1 text-sm" style={{ color: COLORS.plum }}>
              Shop by occasion <ChevronRight size={16} />
            </a>
          </div>
        </div>

        {/* Signature: unwrapping gift box */}
        <div className="flex-1 flex justify-center giftbox-group cursor-pointer" style={{ animation: "floatSlow 5s ease-in-out infinite" }}>
          <svg width="280" height="260" viewBox="0 0 280 260">
            <g className="sparkle-1" style={{ opacity: 0 }}>
              <path d="M80 40 l4 10 10 4 -10 4 -4 10 -4 -10 -10 -4 10 -4z" fill={COLORS.gold} />
            </g>
            <g className="sparkle-2" style={{ opacity: 0 }}>
              <path d="M200 55 l3 8 8 3 -8 3 -3 8 -3 -8 -8 -3 8 -3z" fill={COLORS.orchid} />
            </g>
            <g className="sparkle-3" style={{ opacity: 0 }}>
              <path d="M140 20 l3 8 8 3 -8 3 -3 8 -3 -8 -8 -3 8 -3z" fill={COLORS.gold} />
            </g>
            <rect x="60" y="120" width="160" height="110" rx="10" fill={COLORS.violet} />
            <rect x="128" y="120" width="24" height="110" fill={COLORS.gold} />
            <g className="giftbox-lid">
              <rect x="50" y="95" width="180" height="35" rx="8" fill={COLORS.orchid} />
              <rect x="128" y="95" width="24" height="35" fill={COLORS.gold} />
              <path d="M140 95 C110 60 90 60 95 90 C98 105 120 100 140 95 Z" fill={COLORS.gold} />
              <path d="M140 95 C170 60 190 60 185 90 C182 105 160 100 140 95 Z" fill={COLORS.gold} />
            </g>
          </svg>
        </div>
      </section>

      {/* Occasions */}
      <section id="occasions" className="max-w-6xl mx-auto px-6 pb-6">
        <div className="flex gap-3 overflow-x-auto pb-2">
          {OCCASIONS.map((occ) => (
            <span
              key={occ}
              className="whitespace-nowrap text-sm px-4 py-2 rounded-full border cursor-pointer hover:opacity-80"
              style={{ borderColor: COLORS.orchid, color: COLORS.violet }}
            >
              {occ}
            </span>
          ))}
        </div>
      </section>

      {/* Products */}
      <section id="shop" className="max-w-6xl mx-auto px-6 py-12">
        <div className="flex items-end justify-between mb-6">
          <h2 className="text-2xl" style={{ fontFamily: "'Fraunces', serif", color: COLORS.plum }}>
            Featured gifts
          </h2>
          <a href="#" className="text-sm flex items-center gap-1" style={{ color: COLORS.violet }}>
            View all <ChevronRight size={14} />
          </a>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {PRODUCTS.map((p) => (
            <ProductCard key={p.id} product={p} onAdd={addToCart} />
          ))}
        </div>
      </section>

      {/* Trust strip */}
      <section className="py-10" style={{ backgroundColor: "#F1E7FB" }}>
        <div className="max-w-6xl mx-auto px-6 grid grid-cols-1 sm:grid-cols-3 gap-8 text-sm">
          <div className="flex items-center gap-3">
            <PackageCheck size={22} color={COLORS.violet} />
            <span>Hand-wrapped, every order</span>
          </div>
          <div className="flex items-center gap-3">
            <Truck size={22} color={COLORS.violet} />
            <span>Free shipping over $50</span>
          </div>
          <div className="flex items-center gap-3">
            <Star size={22} color={COLORS.violet} />
            <span>Rated 4.9 by 3,200+ gifters</span>
          </div>
        </div>
      </section>

      {/* Footer */}
      <footer className="py-12" style={{ backgroundColor: COLORS.plum, color: "#EADFF7" }}>
        <div className="max-w-6xl mx-auto px-6 flex flex-col md:flex-row justify-between gap-8">
          <div>
            <div className="flex items-center gap-2 mb-3">
              <Gift size={18} />
              <span style={{ fontFamily: "'Fraunces', serif" }}>The Purple Gifts</span>
            </div>
            <p className="text-sm max-w-xs opacity-80">Thoughtful, small-batch gifts for the people who matter most.</p>
          </div>
          <div className="flex gap-16 text-sm">
            <div className="flex flex-col gap-2">
              <span className="opacity-60 mb-1">Shop</span>
              <a href="#">All gifts</a>
              <a href="#">Occasions</a>
              <a href="#">Best sellers</a>
            </div>
            <div className="flex flex-col gap-2">
              <span className="opacity-60 mb-1">Company</span>
              <a href="#">About</a>
              <a href="#">Journal</a>
              <a href="#">Contact</a>
            </div>
          </div>
        </div>
      </footer>

      {/* Cart Drawer */}
      {cartOpen && (
        <div className="fixed inset-0 z-40 flex justify-end">
          <div className="absolute inset-0 bg-black opacity-30" onClick={() => setCartOpen(false)} />
          <div className="relative w-full max-w-sm h-full p-6 flex flex-col" style={{ backgroundColor: COLORS.cream }}>
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-lg" style={{ fontFamily: "'Fraunces', serif", color: COLORS.plum }}>
                Your cart
              </h3>
              <button onClick={() => setCartOpen(false)}>
                <X size={20} />
              </button>
            </div>
            {cart.length === 0 ? (
              <p className="text-sm opacity-70">Nothing in here yet — go find something lovely.</p>
            ) : (
              <div className="flex flex-col gap-4 overflow-y-auto flex-1">
                {cart.map((item) => (
                  <div key={item.id} className="flex items-center justify-between gap-3">
                    <div>
                      <p className="text-sm font-medium">{item.name}</p>
                      <p className="text-xs opacity-60">${item.price} each</p>
                    </div>
                    <div className="flex items-center gap-2">
                      <button onClick={() => changeQty(item.id, -1)} className="w-6 h-6 rounded-full border flex items-center justify-center">
                        <Minus size={12} />
                      </button>
                      <span className="text-sm w-4 text-center">{item.qty}</span>
                      <button onClick={() => changeQty(item.id, 1)} className="w-6 h-6 rounded-full border flex items-center justify-center">
                        <Plus size={12} />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
            {cart.length > 0 && (
              <div className="pt-4 mt-4 border-t">
                <div className="flex justify-between text-sm mb-4">
                  <span>Subtotal</span>
                  <span className="font-semibold">${cartTotal}</span>
                </div>
                <button className="w-full py-3 rounded-full text-sm font-medium" style={{ backgroundColor: COLORS.violet, color: "#fff" }}>
                  Checkout
                </button>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
